  if(r.stop==='de Sitter escape') return 'transient';
  if(r.stop==='step budget') return 'transient';
  const q=r.trace.map(s=>[s.bp,s.bm,s.pp,s.pm]), n=q.length;
  const sc=Math.max(1e-12,Math.max(...q.map(v=>Math.hypot(...v))));
  let rec=Infinity;
  for(let i=Math.floor(n*0.2);i<n;i++) rec=Math.min(rec,Math.hypot(...q[i].map((v,k)=>v-q[0][k]))/sc);
