const civpLerp=(a,b,u)=>a+(b-a)*Math.max(0,Math.min(1,u));

const civpStep=(a,b,u)=>Math.round(civpLerp(a,b,u));

function civpSphere(re,im,R){const d=1+re*re+im*im;return [2*re*R/d,((re*re+im*im-1)/d)*R,2*im*R/d];}

function civpRing(cx,cy,cz,r,axis,seg){
  const out=[],n=seg||96;
  for(let i=0;i<=n;i++){const t=2*Math.PI*i/n,c=Math.cos(t),s=Math.sin(t);
    out.push(axis===1?[cx+r*c,cy,cz+r*s]:axis===2?[cx+r*c,cy+r*s,cz]:[cx,cy+r*c,cz+r*s]);}
  return out;}

