const FRAC_RULES={
  menger:{name:'Menger sponge', r:3, solid:'box',
    cells:(()=>{const o=[];for(let x=0;x<3;x++)for(let y=0;y<3;y++)for(let z=0;z<3;z++){
      if(((x===1)+(y===1)+(z===1))<=1) o.push([x,y,z]); } return o;})(),
    note:'the 3×3×3 cube with the middle of every face and the centre removed — twenty copies of itself'},
  carpet:{name:'Sierpiński carpet', r:3, solid:'box',
    cells:(()=>{const o=[];for(let x=0;x<3;x++)for(let y=0;y<3;y++) if(!(x===1&&y===1)) o.push([x,y,0]); return o;})(),
    note:'the same removal in the plane: eight copies, and a dimension between a curve and a surface'},
  dust:{name:'Cantor dust', r:3, solid:'box',
    cells:(()=>{const o=[];for(const x of[0,2])for(const y of[0,2])for(const z of[0,2]) o.push([x,y,z]); return o;})(),
    note:'the Cantor set cubed — eight corners, totally disconnected, and EXACTLY the dimension of the carpet'},
  vicsek:{name:'Vicsek cross', r:3, solid:'box',
    cells:[[1,1,1],[0,1,1],[2,1,1],[1,0,1],[1,2,1],[1,1,0],[1,1,2]],
    note:'a centre and its six face neighbours: connected where the dust is not, and lower-dimensional than either'},
  tetra:{name:'Sierpiński tetrahedron', r:2, solid:'tetra',
    cells:[[0,0,0],[1,0,0],[0,1,0],[0,0,1]],
    note:'four half-scale copies at the corners — dimension exactly 2, a fractal that is not fractional at all'}
};

const fracDimension=(N,r)=>Math.log(N)/Math.log(r);

const fracExactDimension=k=>{const R=FRAC_RULES[k]; return fracDimension(R.cells.length,R.r);};

function fracBuild(kind,depth){
  const R=FRAC_RULES[kind]; if(!R) return {pts:[],size:1};
  let pts=[[0,0,0]], s=1;
  for(let d=0;d<depth;d++){ const nx=[]; s/=R.r;
    for(let i=0;i<pts.length;i++){ const p=pts[i];
      for(let j=0;j<R.cells.length;j++){ const c=R.cells[j];
        nx.push([p[0]+c[0]*s, p[1]+c[1]*s, p[2]+c[2]*s]); } }
    pts=nx; }
  /* CENTRES, not corners. A corner lies exactly on a box boundary and floor() then splits
     it unpredictably — which is what made the first box-counting measurement of this
     return 2.50 for a sponge whose dimension is 2.727. */
  return {pts:pts.map(q=>[q[0]+s/2,q[1]+s/2,q[2]+s/2]), size:s};
}

function fracBoxCount(pts,eps){
  const seen=new Set();
  for(let i=0;i<pts.length;i++)
    seen.add(Math.floor(pts[i][0]/eps)+'|'+Math.floor(pts[i][1]/eps)+'|'+Math.floor(pts[i][2]/eps));
  return seen.size;
}

function fracMeasuredDimension(kind,depth){
  const R=FRAC_RULES[kind], {pts}=fracBuild(kind,depth);
  const e1=Math.pow(1/R.r,Math.max(1,depth-2)), e2=Math.pow(1/R.r,depth);
  const n1=fracBoxCount(pts,e1), n2=fracBoxCount(pts,e2);
  return Math.log(n2/n1)/Math.log(e1/e2);
}

const fracCellCount=(kind,depth)=>Math.pow(FRAC_RULES[kind].cells.length,depth);

const LAB_DOMAIN_ORDER=['invariance','geometry','dynamics','quantum','waves','thermo','astro','other'];

function xrLabIds(){
  const all=Object.keys(S3_VIEW_NAMES);
  const seen=new Set();
  const out=[];
  for(const d of LAB_DOMAIN_ORDER) for(const v of all)
    if(!seen.has(v)&&labDomainOf(v)===d){ seen.add(v); out.push(v); }
  for(const v of all) if(!seen.has(v)){ seen.add(v); out.push(v); }   // nothing may fall out
  return out;
}

function xrLabHeadCounts(){
  if(xrLabHeadCounts._c) return xrLabHeadCounts._c;
  const c=new Map();
  for(const id of Object.keys(S3_VIEW_NAMES)){
    const t=String(S3_VIEW_NAMES[id]||id), d=t.indexOf(' · ');
    const h=(d>0?t.slice(0,d):t).toLowerCase();
    c.set(h,(c.get(h)||0)+1);
  }
  xrLabHeadCounts._c=c; return c;
}

function xrLabShort(v,max){
  const M=max||20;
  const full=String((S3_VIEW_NAMES&&S3_VIEW_NAMES[v])||v);
  const d=full.indexOf(' · ');
  let t=full;
  if(d>0){
    const head=full.slice(0,d), tail=full.slice(d+3);
    /* the shared head is the useless one — "CIVP", "S³" — so take the tail there */
    t=(xrLabHeadCounts().get(head.toLowerCase())||0)>1 ? tail : head;
  }
  t=t.trim();
  if(t.length<=M) return t;
  const cut=t.lastIndexOf(' ',M-1);
  return (cut>=10?t.slice(0,cut):t.slice(0,M-1))+'…';
}

const XR_DOM_SHORT={invariance:'⟲ Invar',geometry:'◇ Geom',dynamics:'↻ Dyn',quantum:'⚛ Quant',
  waves:'∿ Waves',thermo:'♨ Therm',astro:'✦ Astro',other:'· Other'};

function xrDomShort(d){ return XR_DOM_SHORT[d]||d; }

function xrLabPickerPlan(opt){
  const o=opt||{};
  const labs=o.labs||xrLabIds();
  const perPage=o.perPage||9, perRow=o.perRow||3;
  const doms=LAB_DOMAIN_ORDER.filter(d=>labs.some(v=>labDomainOf(v)===d));
  const domain=doms.includes(o.domain)?o.domain:doms[0];
  const mine=labs.filter(v=>labDomainOf(v)===domain);
  const pages=Math.max(1,Math.ceil(mine.length/perPage));
  const page=((o.page|0)%pages+pages)%pages;
  const items=mine.slice(page*perPage,page*perPage+perPage);
  const rows=[];
  for(let i=0;i<doms.length;i+=perRow)
    rows.push(doms.slice(i,i+perRow).map(d=>({kind:'domain', id:d,
      label:xrDomShort(d)+' '+labs.filter(v=>labDomainOf(v)===d).length, on:d===domain})));
  for(let i=0;i<items.length;i+=perRow)
    rows.push(items.slice(i,i+perRow).map(v=>({kind:'lab', id:v,
      label:xrLabShort(v), on:v===o.current})));
  if(pages>1) rows.push([{kind:'prev',id:'prev',label:'‹ prev'},
                         {kind:'page',id:'page',label:(page+1)+' / '+pages},
                         {kind:'next',id:'next',label:'next ›'}]);
  return {domain, domains:doms, page, pages, items, rows};
}

let xrLabRecent=[];

function xrLabRemember(v){
  if(!v||!S3_VIEW_NAMES[v]) return xrLabRecent;
  xrLabRecent=[v,...xrLabRecent.filter(x=>x!==v)].slice(0,8);
  return xrLabRecent;
}

function labDomainOf(v){
  /* The suite overrides the visual-identity registry for GROUPING only; the palette
     registry is left untouched so nothing about how these laboratories look changes. */
  if(INVARIANCE_VIEWS.includes(v)) return 'invariance';
  for(const [k,set] of Object.entries(PREMIUM_VIEW_DOMAINS)) if(set.has(v)) return k;
  return 'other';
}

function labNamesAllLangs(id){
  let out=String((S3_VIEW_NAMES&&S3_VIEW_NAMES[id])||'');
  try{ for(const L of Object.values(S3_VIEW_I18N)) if(L&&L[id]) out+=' '+L[id]; }catch(e){}
  return out;
}

